package main

import (
	"context"
	"errors"
	"log"
	"net/http"
	"os/signal"
	"syscall"
	"time"
)

func main() {
	// Cancel ctx when SIGINT or SIGTERM arrives.
	ctx, stop := signal.NotifyContext(context.Background(), syscall.SIGINT, syscall.SIGTERM)
	defer stop()

	srv := &http.Server{Addr: ":8080"}

	// Run the server; ListenAndServe blocks, so launch it in a goroutine.
	go func() {
		if err := srv.ListenAndServe(); err != nil && !errors.Is(err, http.ErrServerClosed) {
			log.Fatalf("listen: %v", err) // a real bind error
		}
	}()
	log.Println("listening on :8080")

	<-ctx.Done() // block until a signal cancels ctx
	log.Println("shutdown signal received, draining...")

	// Bound the drain so a stuck handler can't hang the deploy.
	shutCtx, cancel := context.WithTimeout(context.Background(), 25*time.Second)
	defer cancel()
	if err := srv.Shutdown(shutCtx); err != nil {
		log.Printf("graceful shutdown failed: %v; forcing close", err)
		_ = srv.Close() // last-resort hard kill
	}
	log.Println("shutdown complete")
}

