import (
	"context"
	"log"
	"net/http"
	"time"
)

type DB struct{}

func (DB) Close() error { log.Println("db closed"); return nil }

func main() {
	db := DB{}
	srv := &http.Server{Addr: ":8080"}
	go srv.ListenAndServe()

	// pretend a signal arrived here
	ctx, cancel := context.WithTimeout(context.Background(), 25*time.Second)
	defer cancel()

	// 1) Stop accepting and drain in-flight handlers FIRST.
	if err := srv.Shutdown(ctx); err != nil {
		log.Printf("http shutdown: %v", err)
	}
	// 2) Only after handlers have returned, close what they depended on.
	if err := db.Close(); err != nil {
		log.Printf("db close: %v", err)
	}
	log.Println("done")
}

