package solution

import (
	"context"
	"fmt"
	"time"
)

// Step is one phase of shutdown (e.g. "drain-http", "close-db").
type Step struct {
	Name string
	Run  func(ctx context.Context) error
}

// Shutdown runs steps in order under a single shared deadline.
// It stops at the first failing step (or when the deadline is
// exceeded) and returns an error naming the offending step.
func Shutdown(steps []Step, deadline time.Duration) error {
	ctx, cancel := context.WithTimeout(context.Background(), deadline)
	defer cancel() // always release the timer

	for _, s := range steps {
		// If we've already run out of time, fail before starting.
		if err := ctx.Err(); err != nil {
			return fmt.Errorf("step %q: %w", s.Name, err)
		}
		// Run the step under the shared deadline so it can observe
		// cancellation and bail out early.
		if err := s.Run(ctx); err != nil {
			return fmt.Errorf("step %q: %w", s.Name, err)
		}
	}
	return nil
}

