package solution

import (
	"context"
	"errors"
	"testing"
	"time"
)

func TestShutdownOrderAndSuccess(t *testing.T) {
	var order []string
	mk := func(name string) Step {
		return Step{Name: name, Run: func(ctx context.Context) error {
			order = append(order, name)
			return nil
		}}
	}
	steps := []Step{mk("drain-http"), mk("close-db"), mk("flush-logs")}
	if err := Shutdown(steps, time.Second); err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	want := []string{"drain-http", "close-db", "flush-logs"}
	if len(order) != len(want) {
		t.Fatalf("ran %v want %v", order, want)
	}
	for i := range want {
		if order[i] != want[i] {
			t.Fatalf("order=%v want %v", order, want)
		}
	}
}

func TestShutdownStopsOnError(t *testing.T) {
	ran := 0
	boom := errors.New("boom")
	steps := []Step{
		{Name: "ok", Run: func(ctx context.Context) error { ran++; return nil }},
		{Name: "bad", Run: func(ctx context.Context) error { ran++; return boom }},
		{Name: "never", Run: func(ctx context.Context) error { ran++; return nil }},
	}
	err := Shutdown(steps, time.Second)
	if err == nil {
		t.Fatal("expected error")
	}
	if !errors.Is(err, boom) {
		t.Fatalf("error %v should wrap boom", err)
	}
	if ran != 2 {
		t.Fatalf("ran %d steps want 2 (must stop after failure)", ran)
	}
}

func TestShutdownRespectsDeadline(t *testing.T) {
	steps := []Step{
		{Name: "slow", Run: func(ctx context.Context) error {
			// Honor cancellation instead of really sleeping.
			select {
			case <-ctx.Done():
				return ctx.Err()
			case <-time.After(time.Hour):
				return nil
			}
		}},
	}
	err := Shutdown(steps, 10*time.Millisecond)
	if err == nil {
		t.Fatal("expected deadline error")
	}
	if !errors.Is(err, context.DeadlineExceeded) {
		t.Fatalf("error %v should wrap context.DeadlineExceeded", err)
	}
}

