func main() {
	ctx, stop := signal.NotifyContext(context.Background(),
		syscall.SIGINT, syscall.SIGTERM)
	defer stop()

	srv := &http.Server{Addr: ":8080"}
	go func() {
		if err := srv.ListenAndServe(); err != nil &&
			!errors.Is(err, http.ErrServerClosed) {
			log.Fatalf("listen: %v", err)
		}
	}()

	<-ctx.Done()
	log.Println("shutdown signal received, draining")

	// Fresh, bounded context — NOT the cancelled signal ctx.
	shutCtx, cancel := context.WithTimeout(context.Background(), 25*time.Second)
	defer cancel()
	if err := srv.Shutdown(shutCtx); err != nil {
		log.Printf("drain exceeded deadline: %v; forcing close", err)
		_ = srv.Close() // only now is a hard close acceptable
	}
	log.Println("shutdown complete")
}

func Run(ctx context.Context, srv *http.Server) error {
	g, gctx := errgroup.WithContext(ctx)

	// 1) Serve. A clean shutdown surfaces as ErrServerClosed.
	g.Go(func() error {
		if err := srv.ListenAndServe(); err != nil &&
			!errors.Is(err, http.ErrServerClosed) {
			return err
		}
		return nil
	})

	// 2) When the shared ctx is cancelled (signal or sibling error),
	//    drain with a FRESH bounded context.
	g.Go(func() error {
		<-gctx.Done()
		shutCtx, cancel := context.WithTimeout(
			context.Background(), 25*time.Second)
		defer cancel()
		return srv.Shutdown(shutCtx)
	})

	return g.Wait() // first non-nil error, or nil on clean stop
}
